import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Checkbox","description":"","frontmatter":{},"headers":[],"relativePath":"components/checkbox.md","filePath":"components/checkbox.md"}'),r={name:"components/checkbox.md"};function c(i,e,h,s,n,l){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="checkbox" tabindex="-1">Checkbox <a class="header-anchor" href="#checkbox" aria-label="Permalink to &quot;Checkbox&quot;">​</a></h1><p>Checkbox is a choice among several, or a confirmation.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for options that are chosen together and saved with a form, and for the selection of the items of a list or the rows of a table. <code>indeterminate</code> shows that some of them are selected. A setting that takes effect at once is a <a href="./toggle">Toggle</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>checked</code></td><td><code>false</code></td><td>The state (bindable)</td></tr><tr><td><code>indeterminate</code></td><td><code>false</code></td><td>Some of a list is selected</td></tr><tr><td><code>label</code></td><td></td><td>The text beside the box</td></tr><tr><td><code>ariaLabel</code></td><td></td><td>The accessible name when there is no text</td></tr><tr><td><code>disabled</code></td><td><code>false</code></td><td>Cannot be changed</td></tr><tr><td><code>id</code></td><td></td><td>The id of the input</td></tr><tr><td><code>onchange</code></td><td></td><td>Called with the new state</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The control is as high as a small button, and the whole of it is pressed, text included. The box is a native checkbox, the square of an icon with one line; checked, it takes the solid surface and a check mark; indeterminate, the stronger raise surface without a mark. The text is gap-sm from the box, one line, trimmed to its ink. Disabled is dimmed.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/checkbox/" title="Checkbox" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/checkbox/" target="_blank" rel="noopener">Checkbox</a></figcaption></figure>',10)])])}const p=t(r,[["render",c]]);export{m as __pageData,p as default};
